import{_ as l,o as e,c as s,a2 as a}from"./chunks/framework.Ch4PdLd_.js";const h=JSON.parse('{"title":"Skills","description":"","frontmatter":{},"headers":[],"relativePath":"customize/skills.md","filePath":"customize/skills.md"}'),i={name:"customize/skills.md"};function n(d,t,o,r,c,p){return e(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h1><p>Skill 为某一类工作提供专项说明和配套文件。nek 只把每个 Skill 的名字和描述告诉模型，任务需要时模型才读取完整的说明。这样详细的指导不会一直占用上下文。</p><p>当一个工作流程需要比提示词模板更多的上下文、但又不需要新的可执行能力时，用 Skill。Skill 可以附带脚本、参考资料和其他资源。</p><p>nek 实现了 <a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">Agent Skills 规范</a>。大多数无效字段只产生警告，不会阻止启动。</p><h2 id="创建-skill" tabindex="-1">创建 Skill <a class="header-anchor" href="#创建-skill" aria-label="Permalink to &quot;创建 Skill&quot;">​</a></h2><p>一个 Skill 是一个包含 <code>SKILL.md</code> 的目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pdf-tools/</span></span>
<span class="line"><span>├── SKILL.md</span></span>
<span class="line"><span>├── scripts/</span></span>
<span class="line"><span>│   └── extract.sh</span></span>
<span class="line"><span>├── references/</span></span>
<span class="line"><span>│   └── formats.md</span></span>
<span class="line"><span>└── assets/</span></span>
<span class="line"><span>    └── template.json</span></span></code></pre></div><p><code>SKILL.md</code> 以 frontmatter 开头，后面是直接的说明：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name: pdf-tools</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Extract text and tables from PDF files. Use when reading, converting, or inspecting PDFs.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># PDF tools</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Read </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`references/formats.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> before converting a document. Run scripts relative to this skill directory.</span></span></code></pre></div><p><strong>描述决定模型何时考虑加载这个 Skill。</strong> 同时写清楚“它做什么”和“什么时候用”。像“帮助处理 PDF”这样的描述提供的信息不够。</p><p>引用附带的文件时使用相对于 Skill 目录的路径，nek 会告诉模型 Skill 所在的位置，让它能解析这些路径。</p><h2 id="skill-如何加载" tabindex="-1">Skill 如何加载 <a class="header-anchor" href="#skill-如何加载" aria-label="Permalink to &quot;Skill 如何加载&quot;">​</a></h2><ol><li>启动时，nek 扫描配置的 Skill 位置，把每个 Skill 的名字、描述和路径加入系统提示词（不含完整说明）；</li><li>任务匹配时，模型读取 <code>SKILL.md</code> 并按说明工作。</li></ol><p>模型有可能没有加载一个相关的 Skill。需要强制使用时，用 <code>/skill:名字</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/skill:pdf-tools extract report.pdf</span></span></code></pre></div><p>命令后面的参数会作为用户请求附加在加载的说明之后。</p><ul><li>frontmatter 中设置 <code>disable-model-invocation: true</code>：Skill 不出现在模型的自动选择里，只能通过命令使用。</li><li>设置 <code>enableSkillCommands</code>（默认 <code>true</code>）控制 Skill 命令是否出现在命令补全里；手动输入的 <code>/skill:名字</code> 始终有效。</li></ul><h2 id="locations" tabindex="-1">放在哪里 <a class="header-anchor" href="#locations" aria-label="Permalink to &quot;放在哪里 {#locations}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>作用范围</th></tr></thead><tbody><tr><td><code>~/.nek/agent/skills/</code></td><td>用户级</td></tr><tr><td><code>~/.agents/skills/</code></td><td>用户级（Agent Skills 通用位置）</td></tr><tr><td><code>.nek/skills/</code></td><td>项目级，信任项目后加载</td></tr><tr><td><code>.agents/skills/</code></td><td>项目级，从工作目录向上查找各级目录（有仓库时到仓库根为止），信任项目后加载</td></tr><tr><td>设置 <code>skills</code></td><td>额外的文件或目录</td></tr><tr><td><code>--skill &lt;路径&gt;</code></td><td>只对本次运行生效（可重复）</td></tr></tbody></table><p>包含 <code>SKILL.md</code> 的目录会被递归发现。nek 也接受部分独立的 Markdown Skill 文件，但包含 <code>SKILL.md</code> 的目录是可移植的形式，推荐使用。</p><p><code>--no-skills</code>（<code>-ns</code>）关闭 Skill 的自动发现和配置加载，显式的 <code>--skill</code> 仍然生效。</p><div class="warning custom-block"><p class="custom-block-title">审查项目 Skill</p><p>项目 Skill 可以指示模型运行脚本或修改文件。信任陌生项目前，请检查它的 Skill 及配套文件。</p></div><h2 id="frontmatter-字段" tabindex="-1">frontmatter 字段 <a class="header-anchor" href="#frontmatter-字段" aria-label="Permalink to &quot;frontmatter 字段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>作用</th></tr></thead><tbody><tr><td><code>name</code></td><td>命令名和显示名</td></tr><tr><td><code>description</code></td><td>给模型看的路由描述</td></tr><tr><td><code>license</code></td><td>许可证名称或附带的许可证文件</td></tr><tr><td><code>compatibility</code></td><td>环境要求</td></tr><tr><td><code>metadata</code></td><td>额外的键值元数据</td></tr><tr><td><code>allowed-tools</code></td><td>实验性的预批准工具列表</td></tr><tr><td><code>disable-model-invocation</code></td><td>不参与模型的自动选择</td></tr></tbody></table><p>规则：</p><ul><li>名字只能用小写字母、数字和连字符，不能以连字符开头或结尾，也不能有连续的连字符，最多 64 个字符；描述最多 1024 个字符。</li><li>nek 不要求名字与所在目录同名，也不会因此警告；但其他 Agent Skills 实现可能要求，保持一致更具可移植性。</li><li>格式错误的 <code>SKILL.md</code>、没有描述的 Skill 不会加载。</li><li>名字冲突时保留第一个发现的 Skill 并给出警告。</li></ul><h2 id="验证和分享" tabindex="-1">验证和分享 <a class="header-anchor" href="#验证和分享" aria-label="Permalink to &quot;验证和分享&quot;">​</a></h2><p>在能发现该 Skill 的位置启动 nek，检查启动诊断信息（<code>Ctrl+O</code> 展开启动信息）和 <code>/skill:名字</code> 命令。会话中编辑 Skill 后运行 <code>/reload</code>。</p><p>分享时直接分发整个 Skill 目录即可（例如放进一个 git 仓库，让别人克隆到 <code>~/.nek/agent/skills/</code>）。把环境准备写在 Skill 的说明里，并声明它需要的运行时依赖。</p><p>可以参考的 Skill 集合：<a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">Anthropic skills</a>、<a href="https://github.com/badlogic/pi-skills" target="_blank" rel="noreferrer">pi-skills</a>。</p>`,30)])])}const g=l(i,[["render",n]]);export{h as __pageData,g as default};
